import type { CefrLevel } from './content'

/** Authored communicative practice, not an official CEFR assessment or certification. */
export interface CourseStrand { id: string; title: string; description: string }
export interface CourseTurn {
  id: string
  context: string
  npcLine: string
  instruction: string
  example: string
  alternatives?: string[]
  hint: string
  transferContext: string
  transferInstruction: string
  transferExample: string
}
export interface CourseLesson {
  id: string
  level: CefrLevel
  strandId: string
  title: string
  canDo: string
  grammar: string[]
  turns: CourseTurn[]
}
export const courseStrands: CourseStrand[] = [
  { id: 'social', title: 'People and connection', description: 'Greet, introduce, invite, support and navigate relationships.' },
  { id: 'questions', title: 'Questions and clarification', description: 'Ask where, when and why; check assumptions and repair misunderstandings.' },
  { id: 'routines', title: 'Life and time', description: 'Describe routines, recount experiences and reflect on change.' },
  { id: 'food', title: 'Food and hospitality', description: 'Order, cook, host and negotiate preferences without awkwardness.' },
  { id: 'shopping', title: 'Shopping and services', description: 'Choose, compare, return purchases and resolve service problems.' },
  { id: 'travel', title: 'Travel and arrangements', description: 'Find your way, book, adapt plans and handle disruption.' },
  { id: 'home', title: 'Home and practical projects', description: 'Describe spaces, organise tasks and negotiate practical work.' },
  { id: 'health', title: 'Health and wellbeing', description: 'Describe how you feel, arrange care and clarify choices.' },
  { id: 'work', title: 'Work and learning', description: 'Explain roles, learn together, give feedback and lead discussions.' },
  { id: 'culture', title: 'Culture and ideas', description: 'Discuss music, stories, performances and interpretations.' },
  { id: 'community', title: 'Community and public life', description: 'Take part locally, weigh competing needs and discuss public issues.' },
  { id: 'mediation', title: 'Helping people understand', description: 'Relay information, explain differences and reconcile viewpoints.' },
]
export const courseLevels: { level: CefrLevel; title: string; description: string }[] = [
  { level: 'A1', title: 'First connections', description: 'Short familiar exchanges, useful questions and permission to pause or ask for repetition.' },
  { level: 'A2', title: 'Everyday independence', description: 'Routine transactions, simple past experiences and practical arrangements.' },
  { level: 'B1', title: 'Keep the conversation going', description: 'Explain reasons, narrate events, solve familiar problems and ask follow-up questions.' },
  { level: 'B2', title: 'Discuss and negotiate', description: 'Sustain a viewpoint, negotiate outcomes and respond flexibly to complications.' },
  { level: 'C1', title: 'Precision and tact', description: 'Handle implicit meaning, nuanced disagreement, register and complex explanations.' },
  { level: 'C2', title: 'Flexible, nuanced command', description: 'Reformulate precisely, reconcile perspectives and handle ambiguity, humour and sensitive interaction.' },
]

type TurnSeed = [npc: string, task: string, example: string, hint: string, transferContext: string, transferTask: string, transferExample: string]
const lessons: CourseLesson[] = []
export const courseLessons: CourseLesson[] = lessons
function episode(level: CefrLevel, strandId: string, title: string, canDo: string, grammar: string[], context: string, turns: TurnSeed[]) {
  const id = `conversation-${level.toLowerCase()}-${strandId}`
  lessons.push({ id, level, strandId, title, canDo, grammar, turns: turns.map((t, index) => ({
    id: `${id}-${index + 1}`, context, npcLine: t[0], instruction: t[1], example: t[2], hint: t[3],
    transferContext: t[4], transferInstruction: t[5], transferExample: t[6],
  })) })
}

