episode('B1', 'social', 'An invitation with a complication', 'Keep a social exchange going while negotiating different needs.', ['conditional requests', 'past narration', 'reason clauses'], 'You are arranging an evening with friends who have different preferences.', [
  ['Pensavo a una cena fuori. Ti va?', 'Accept, but explain that you would prefer somewhere quiet so you can talk.', 'Volentieri, ma preferirei un posto tranquillo per poter parlare.', 'Accept before explaining your preference.', 'Friends propose a busy festival.', 'Say you would enjoy meeting them but would prefer a quieter café.', 'Mi farebbe piacere vedervi, ma preferirei un bar più tranquillo.'],
  ['Perché non torniamo al locale dell’ultima volta?', 'Explain that the food was good but you could not hear each other.', 'Si mangiava bene, ma c’era troppo rumore e non riuscivamo a sentirci.', 'Separate the positive and the difficulty.', 'A friend suggests repeating a group walk.', 'Explain that it was beautiful but too long for you.', 'Era una bella passeggiata, ma per me era troppo lunga.'],
  ['Allora scegli tu.', 'Suggest somewhere you would enjoy going and check whether everyone can manage a time you choose.', 'Potremmo provare quel ristorante piccolo. Alle sette e mezzo va bene a tutti?', 'Make a proposal and check agreement.', 'You need to choose a day for a shared picnic.', 'Suggest Sunday and ask whether everyone is free.', 'Potremmo fare domenica. Siete tutti liberi?'],
])
episode('B1', 'questions', 'When instructions are unclear', 'Identify missing information and repair a misunderstanding.', ['indirect questions', 'modal verbs', 'quindi'], 'You have received vague instructions for an evening workshop.', [
  ['Porta quello che serve per il laboratorio.', 'Ask them to explain exactly what you should bring.', 'Mi puoi spiegare esattamente che cosa devo portare?', 'Ask for a specific missing detail.', 'A builder asks you to prepare the room.', 'Ask exactly which furniture you should move.', 'Mi puoi dire quali mobili devo spostare?'],
  ['Servono fogli grandi, non quelli piccoli.', 'Check whether A3 paper is suitable.', 'Quindi vanno bene i fogli A3?', 'Check your interpretation.', 'A host requests something without alcohol.', 'Check whether fruit juice is suitable.', 'Quindi va bene del succo di frutta?'],
  ['No, pensavo che fossi già iscritto.', 'Explain that you misunderstood and ask how to register.', 'Scusa, avevo capito male. Come faccio a iscrivermi?', 'Acknowledge the misunderstanding and move forward.', 'You discover collection requires an appointment.', 'Say you did not know and ask how to book one.', 'Non lo sapevo. Come posso prenotare un appuntamento?'],
])
episode('B1', 'routines', 'Plans interrupted', 'Narrate an interrupted plan and explain what changed.', ['imperfetto / passato prossimo', 'mentre', 'sequence markers'], 'You explain why your day did not go as planned.', [
  ['Com’è andata la giornata?', 'Say you were working in the garden when it started raining.', 'Stavo lavorando in giardino quando ha cominciato a piovere.', 'Background activity, then a new event.', 'A friend asks about your journey.', 'Say you were waiting for the bus when they cancelled it.', 'Aspettavo l’autobus quando hanno annunciato che era cancellato.'],
  ['E allora che cosa hai fatto?', 'Say you went inside and finished a book instead.', 'Sono rientrato e invece ho finito un libro.', 'Keep the order of events clear.', 'Your outdoor lunch was interrupted by rain.', 'Say you moved everything indoors and ate in the kitchen.', 'Abbiamo portato tutto dentro e abbiamo mangiato in cucina.'],
  ['Ti capita spesso di cambiare programma?', 'Say you used to get annoyed, but now you find it easier.', 'Prima mi arrabbiavo, ma adesso mi viene più facile cambiare programma.', 'Contrast then and now.', 'Someone asks whether you still rush every morning.', 'Say you used to rush but now organise things the night before.', 'Prima avevo sempre fretta; adesso preparo tutto la sera prima.'],
])
episode('B1', 'food', 'A meal everyone can enjoy', 'Clarify dietary needs and adapt a shared meal.', ['conditional suggestions', 'ne / direct pronouns', 'purpose'], 'You are planning lunch for friends with different food preferences.', [
  ['Una delle ospiti non mangia latticini.', 'Ask whether she eats eggs, so you can choose a suitable dish.', 'Sai se mangia le uova? Così posso scegliere un piatto adatto.', 'Ask rather than assume.', 'You hear a guest avoids meat.', 'Ask whether they eat fish before choosing the menu.', 'Sai se mangia pesce? Vorrei scegliere un menù adatto.'],
  ['La torta contiene burro.', 'Suggest preparing a fruit salad instead and making enough for six.', 'Potremmo preparare una macedonia e farne abbastanza per sei persone.', 'Propose a workable alternative.', 'A soup contains cream.', 'Suggest making a second version without it.', 'Potremmo prepararne un’altra senza panna.'],
  ['Sono rimaste quattro porzioni.', 'Say you will keep two and take two to the neighbours.', 'Ne tengo due e ne porto due ai vicini.', 'Preserve both quantities.', 'You have six bread rolls left.', 'Say you will freeze four and use two tomorrow.', 'Ne congelo quattro e ne uso due domani.'],
])
episode('B1', 'shopping', 'A delivery that never arrived', 'Explain a sequence, request action and check the next step.', ['passato prossimo', 'non ancora', 'future'], 'You telephone about an order that has not arrived.', [
  ['Mi spiega che cosa è successo?', 'Say you ordered a lamp last week, paid for it, but have not received it.', 'Ho ordinato una lampada la settimana scorsa e l’ho pagata, ma non l’ho ancora ricevuta.', 'Keep the same item across the three facts.', 'You call about concert tickets.', 'Say you bought them on Monday but have not received them.', 'Li ho comprati lunedì, ma non li ho ancora ricevuti.'],
  ['Forse arriverà la prossima settimana.', 'Explain you need it by Friday and ask them to check.', 'Mi serve entro venerdì. Potrebbe controllare la consegna?', 'State the deadline and request an action.', 'A repair shop is unsure about collection.', 'Say you need the bicycle tomorrow and ask them to check.', 'Mi serve la bici domani. Può controllare se sarà pronta?'],
  ['La richiamo domani.', 'Ask what time and whether they will also email you.', 'A che ora mi richiama? Può mandarmi anche un’email?', 'Make the follow-up concrete.', 'A supplier promises a refund.', 'Ask when it will arrive and request written confirmation.', 'Quando arriverà il rimborso? Può confermarmelo per iscritto?'],
])
episode('B1', 'travel', 'A missed connection', 'Explain a disruption and negotiate a practical alternative.', ['past causes', 'conditional', 'future arrangements'], 'A delayed train has caused you to miss a connection.', [
  ['Perché non ha preso il treno delle undici?', 'Explain your first train was late and you arrived after it left.', 'Il primo treno era in ritardo e sono arrivato dopo la partenza.', 'Describe the sequence without unnecessary detail.', 'You arrive late at a hotel.', 'Explain the flight was delayed and you missed the last bus.', 'Il volo era in ritardo e ho perso l’ultimo autobus.'],
  ['Il prossimo diretto parte stasera.', 'Ask whether there is an earlier route with a change.', 'C’è un collegamento prima, anche con un cambio?', 'Offer flexibility while keeping your goal.', 'A ferry is full until the afternoon.', 'Ask whether you could travel from another port earlier.', 'Potrei partire prima da un altro porto?'],
  ['Può cambiare a Bologna.', 'Check whether your existing ticket is valid for the whole journey.', 'Il mio biglietto va bene per tutto il viaggio?', 'Confirm the practical consequence.', 'A bus replaces part of your train journey.', 'Ask whether you need to buy another ticket.', 'Devo comprare un altro biglietto?'],
])
episode('B1', 'home', 'Agreeing a practical job', 'Explain a practical goal and agree responsibilities.', ['purpose clauses', 'future', 'object pronouns'], 'You arrange a small garden project with a neighbour.', [
  ['Dove vuoi mettere le nuove piante?', 'Explain you want them near the wall because that area gets sun.', 'Vorrei metterle vicino al muro perché lì c’è il sole.', 'Give location and reason.', 'You are choosing where to put a desk.', 'Explain you want it near the window for more light.', 'Vorrei metterlo vicino alla finestra per avere più luce.'],
  ['Le compri tu o le compro io?', 'Say you will buy them and ask your neighbour to collect them.', 'Le compro io. Potresti ritirarle tu?', 'Divide the responsibilities.', 'You are arranging paint for a shared project.', 'Say you will order it and ask the other person to collect it.', 'La ordino io. Puoi ritirarla tu?'],
  ['E se piove sabato?', 'Suggest doing the indoor work first and postponing planting.', 'Se piove, facciamo prima i lavori dentro e rimandiamo le piante.', 'Offer a simple contingency.', 'You planned to paint outside tomorrow.', 'Say you will prepare the room indoors if the weather is bad.', 'Se fa brutto tempo, prepareremo la stanza dentro.'],
])
episode('B1', 'health', 'Make your concern clear', 'Explain an impact on daily life and ask for clarification.', ['duration', 'used to / now', 'indirect questions'], 'You discuss a health concern; focus on communication rather than medical advice.', [
  ['Che cosa la preoccupa di più?', 'Say the pain stops you sleeping and this has lasted a week.', 'Il dolore non mi lascia dormire e va avanti da una settimana.', 'Describe impact and duration.', 'A clinician asks about a cough.', 'Say it wakes you at night and has lasted ten days.', 'Mi sveglia di notte e dura da dieci giorni.'],
  ['Ha cambiato qualcosa nelle sue attività?', 'Say you used to walk daily but now stop after ten minutes.', 'Prima camminavo tutti i giorni; adesso devo fermarmi dopo dieci minuti.', 'Make the change concrete.', 'Someone asks how tiredness affects you.', 'Say you used to cook every evening but now often need help.', 'Prima cucinavo ogni sera, ma adesso ho spesso bisogno di aiuto.'],
  ['Vediamo come va e poi decidiamo.', 'Ask when you should contact them again and what change to report.', 'Quando dovrei ricontattarvi e quali cambiamenti dovrei segnalare?', 'Request a clear follow-up plan.', 'A professional suggests monitoring a problem.', 'Ask what you should write down before the next appointment.', 'Che cosa dovrei annotare prima del prossimo appuntamento?'],
])
episode('B1', 'work', 'Give useful feedback', 'Describe a difficulty, acknowledge strengths and request a revision.', ['contrasts', 'conditional requests', 'purpose'], 'You and a colleague are preparing a short presentation.', [
  ['Come ti sembra la presentazione?', 'Say the examples are clear but the introduction is too long.', 'Gli esempi sono chiari, ma l’introduzione è un po’ troppo lunga.', 'Be specific about both parts.', 'A friend asks about an event invitation.', 'Say the tone is friendly but the date is hard to find.', 'Il tono è amichevole, ma la data non si trova facilmente.'],
  ['Che cosa cambieresti?', 'Suggest shortening the beginning so there is time for questions.', 'Accorcerei l’inizio per lasciare più tempo alle domande.', 'Link your suggestion to its purpose.', 'A lesson plan has too many activities.', 'Suggest removing one so people can practise more.', 'Toglierei un’attività per lasciare più tempo alla pratica.'],
  ['Puoi controllarla di nuovo domani?', 'Agree, but ask them to send it before lunch.', 'Certo, ma puoi mandarmela prima di pranzo?', 'Accept with a clear practical condition.', 'A colleague asks you to review some notes.', 'Agree and ask them to send them this evening.', 'Volentieri. Puoi mandarmele questa sera?'],
])
episode('B1', 'culture', 'Recommend with reasons', 'Summarise a story and give a supported recommendation.', ['past narration', 'relative clauses', 'opinion phrases'], 'You recommend a book to a friend without spoiling the ending.', [
  ['Di che cosa parla?', 'Say it is about a woman who returns to her village after many years.', 'Parla di una donna che torna al suo paese dopo molti anni.', 'Give the premise, not every event.', 'Someone asks about a film.', 'Say it follows two brothers travelling across Italy.', 'Racconta il viaggio di due fratelli attraverso l’Italia.'],
  ['Che cosa ti è piaciuto?', 'Say the characters felt real, although the start was slow.', 'I personaggi mi sembravano veri, anche se l’inizio era lento.', 'Support your view with a concrete feature.', 'A friend asks about a concert.', 'Say the playing was excellent although the room was uncomfortable.', 'I musicisti erano bravissimi, anche se la sala era scomoda.'],
  ['Pensi che mi piacerà?', 'Recommend it if they enjoy family stories, but warn it is quite sad.', 'Se ti piacciono le storie di famiglia, te lo consiglio, ma è piuttosto triste.', 'Tailor your recommendation to the person.', 'A friend asks about a long museum visit.', 'Recommend it if they like history, but suggest allowing plenty of time.', 'Se ti piace la storia, te lo consiglio, ma prenditi abbastanza tempo.'],
])
episode('B1', 'community', 'A useful local change', 'Explain a community problem and suggest a realistic improvement.', ['opinion', 'conditional proposals', 'reasons'], 'Neighbours discuss improving a shared green space.', [
  ['Che cosa manca in questo parco?', 'Say there are few benches and older visitors need somewhere to rest.', 'Ci sono poche panchine e le persone anziane hanno bisogno di riposare.', 'Connect the problem to people’s needs.', 'Residents discuss a bus stop.', 'Explain that there is no shelter and people get wet.', 'Non c’è una pensilina e quando piove la gente si bagna.'],
  ['Non abbiamo molti soldi.', 'Suggest starting with two benches rather than changing everything.', 'Potremmo cominciare con due panchine invece di cambiare tutto.', 'Make a modest proposal.', 'A local group cannot afford a big event.', 'Suggest starting with a small afternoon gathering.', 'Potremmo iniziare con un piccolo incontro nel pomeriggio.'],
  ['Chi può occuparsene?', 'Offer to find prices and report back next week.', 'Posso cercare i prezzi e riferirvi tutto la settimana prossima.', 'Offer a concrete action and time.', 'A group needs a meeting venue.', 'Offer to telephone two places and report tomorrow.', 'Posso telefonare a due posti e farvi sapere domani.'],
])
episode('B1', 'mediation', 'Explain the useful part', 'Summarise practical information for someone with different needs.', ['reported information', 'sequences', 'clarification'], 'You help a visitor understand a workshop notice.', [
  ['Il laboratorio costa venti euro; il materiale è incluso, ma il pranzo no.', 'Explain what the price covers and what they must arrange separately.', 'I venti euro comprendono il materiale, ma il pranzo va organizzato a parte.', 'Keep included and excluded items distinct.', 'A hotel rate includes breakfast but not parking.', 'Explain what the guest still needs to pay for.', 'La colazione è inclusa, ma il parcheggio si paga a parte.'],
  ['Prima si paga online, poi si riceve il codice da presentare all’ingresso.', 'Explain the two steps in simpler language.', 'Prima paghi online, poi ti arriva un codice: lo fai vedere all’ingresso.', 'Use an ordered sequence.', 'A collection notice requires online booking then photo ID.', 'Explain what your friend should do.', 'Prima prenoti online, poi porti un documento con una foto.'],
  ['Non posso usare il sito: c’è un altro modo?', 'Offer to help them telephone and explain that online booking is difficult for them.', 'Possiamo telefonare insieme e spiegare che per te è difficile prenotare online.', 'Help the person reach their goal.', 'A visitor cannot understand a ticket machine.', 'Offer to go with them to the staffed counter.', 'Possiamo andare insieme alla biglietteria e chiedere aiuto.'],
])

// B2: competing priorities, sustained opinions and flexible negotiation.
episode('B2', 'social', 'Say no without closing the door', 'Decline tactfully and preserve the relationship with an alternative.', ['conditional', 'concession', 'hypothetical possibilities'], 'A friend wants you to join a busy weekend away.', [
  ['Dai, vieni! Abbiamo organizzato tutto.', 'Show appreciation but explain that a full weekend would be too much.', 'Mi fa piacere che abbiate pensato a me, ma un intero fine settimana sarebbe troppo impegnativo.', 'Acknowledge the invitation before setting a boundary.', 'Friends invite you to host a large party.', 'Say you appreciate the idea but cannot host so many people.', 'Mi piace l’idea, ma non me la sento di ospitare così tante persone.'],
  ['Non puoi fare uno sforzo?', 'Hold your boundary warmly and offer to join for Saturday lunch.', 'Capisco che ci teniate, ma preferisco non fermarmi tutto il fine settimana. Potrei raggiungervi per pranzo sabato.', 'Be clear without over-apologising.', 'A friend pressures you to stay out late.', 'Decline the late evening but offer to meet earlier.', 'Stasera non posso fare tardi, ma vi raggiungerei volentieri prima.'],
  ['Pensavo che non volessi più stare con noi.', 'Reassure them that you value their company; the issue is energy, not friendship.', 'Mi fa sempre piacere stare con voi. È una questione di energie, non del nostro rapporto.', 'Address the implied worry directly.', 'A friend interprets your declined invitation as criticism.', 'Explain you value them and simply need more notice.', 'Non c’entra il nostro rapporto: mi fa piacere vederti, ma ho bisogno di un po’ più di preavviso.'],
])
episode('B2', 'questions', 'Test an assumption', 'Ask precise questions without sounding confrontational.', ['indirect questions', 'reported claims', 'conditional'], 'A group is considering a new membership scheme.', [
  ['Tutti vogliono cambiare sistema.', 'Ask how they reached that conclusion and whether everyone was consulted.', 'Posso chiedere su cosa si basa questa conclusione? Sono stati consultati tutti?', 'Question the evidence, not the person.', 'Someone says visitors dislike the opening hours.', 'Ask whether this comes from a survey or individual comments.', 'È emerso da un sondaggio o da singoli commenti?'],
  ['Abbiamo ricevuto cinque messaggi negativi.', 'Acknowledge them but ask how many members there are overall.', 'Sono osservazioni da considerare. Su quanti iscritti, però?', 'Put evidence in context.', 'A shop reports three complaints about delivery.', 'Ask how many orders were delivered in that period.', 'Quante consegne avete fatto nello stesso periodo?'],
  ['Quindi pensi che non ci sia nessun problema?', 'Clarify that you see a possible problem but want to understand its extent.', 'Non dico che non ci sia un problema; vorrei capire quanto sia diffuso prima di decidere.', 'Repair the stronger claim attributed to you.', 'Someone says you oppose a project after you ask about costs.', 'Clarify that you support the goal but need a clear budget.', 'Sostengo l’obiettivo, ma vorrei un bilancio chiaro prima di impegnarci.'],
])
episode('B2', 'routines', 'Explain a change in priorities', 'Reflect on a change and compare benefits with losses.', ['used to / now', 'concession', 'hypothetical past'], 'You discuss how your use of time has changed.', [
  ['Ti manca la vita di prima?', 'Say you miss colleagues but appreciate controlling your own time.', 'Mi mancano i colleghi, ma apprezzo poter organizzare il tempo come voglio.', 'Allow two feelings to coexist.', 'A friend asks about moving to the country.', 'Say you miss the city’s events but enjoy the quieter pace.', 'Mi mancano gli eventi della città, ma mi piace il ritmo più tranquillo.'],
  ['Allora adesso fai tutto con calma?', 'Explain that free time can still become crowded if you accept every invitation.', 'Non necessariamente: se accetto ogni proposta, finisco per riempire di nuovo tutte le giornate.', 'Challenge the oversimplification with an example.', 'Someone assumes working from home always means less stress.', 'Explain that blurred boundaries can make switching off harder.', 'Non sempre: se lavoro e casa si confondono, può diventare più difficile staccare.'],
  ['Che cosa avresti fatto diversamente?', 'Say one thing you would have done differently about your use of time, using your own priorities.', 'Avrei riservato prima più tempo ai miei interessi, invece di rimandarli sempre.', 'Reflect rather than list events.', 'Someone asks about learning a language late.', 'Say you would have started speaking earlier instead of waiting to feel ready.', 'Avrei cominciato a parlare prima, senza aspettare di sentirmi pronto.'],
])
episode('B2', 'food', 'Host with different expectations', 'Negotiate preferences and resolve a hospitality misunderstanding.', ['concession', 'polite conditionals', 'reported speech'], 'You organise a shared dinner with friends.', [
  ['Un menù vegetariano non piacerà a nessuno.', 'Disagree politely, saying several guests prefer it and good food matters more than labels.', 'Non ne sarei così sicuro: alcuni lo preferiscono, e conta soprattutto preparare qualcosa di buono.', 'Challenge the generalisation calmly.', 'Someone dismisses an alcohol-free celebration.', 'Say some guests will welcome it and the atmosphere matters most.', 'Alcuni lo apprezzeranno, e l’atmosfera dipende più dalle persone che dall’alcol.'],
  ['Allora devo preparare tre cene diverse?', 'Suggest a shared base dish with optional additions.', 'Non serve: potremmo preparare un piatto di base per tutti e servire le aggiunte a parte.', 'Find a practical common solution.', 'A picnic group has different tastes.', 'Suggest shared salads with bread and toppings served separately.', 'Facciamo delle insalate per tutti e lasciamo pane e condimenti a parte.'],
  ['Hai detto che la mia torta era troppo dolce!', 'Clarify that you meant it was too sweet for your taste, not badly made.', 'Intendevo dire che era un po’ troppo dolce per i miei gusti, non che fosse fatta male.', 'Separate preference from judgement.', 'A host thinks you criticised their cooking.', 'Explain that you avoid spicy food personally and enjoyed their effort.', 'È una mia preferenza: mangio poco piccante, ma ho apprezzato molto quello che hai preparato.'],
])
episode('B2', 'shopping', 'Negotiate a fair remedy', 'State a problem firmly and negotiate a proportionate remedy.', ['relative clauses', 'conditional alternatives', 'register'], 'A custom-made table arrived damaged and later than agreed.', [
  ['Un piccolo segno può capitare.', 'Explain calmly that the damage is visible and was not mentioned before delivery.', 'Capisco, ma il danno è ben visibile e non mi era stato segnalato prima della consegna.', 'Describe verifiable facts.', 'A service provider minimises repeated missed appointments.', 'Explain that you took time off twice and received no warning.', 'Ho liberato il tempo due volte e non sono stato avvisato in nessuno dei due casi.'],
  ['Possiamo offrirle uno sconto del cinque per cento.', 'Say you would prefer a repair, or a replacement if repair is impossible.', 'Preferirei una riparazione; se non fosse possibile, chiederei una sostituzione.', 'State your preferred remedy and fallback.', 'A damaged suitcase is offered at a discount.', 'Say you need a working zip and would prefer an exchange.', 'Mi serve una cerniera funzionante, quindi preferirei cambiarla.'],
  ['La faremo richiamare.', 'Request a named contact, a deadline and written confirmation.', 'Potrebbe indicarmi una persona di riferimento, una scadenza e confermarmi tutto per iscritto?', 'Turn a vague promise into a concrete next step.', 'A contractor promises to resolve an invoice problem.', 'Ask when and who will send the corrected invoice.', 'Entro quando riceverò la fattura corretta e chi me la invierà?'],
])
episode('B2', 'travel', 'Change the plan together', 'Balance preferences and constraints during travel disruption.', ['hypothetical conditions', 'comparatives', 'negotiation'], 'Heavy rain disrupts a group holiday plan.', [
  ['Abbiamo già pagato l’escursione. Andiamo lo stesso.', 'Acknowledge the cost but argue that conditions should decide whether you go.', 'Capisco che abbiamo pagato, ma dovremmo decidere in base alle condizioni, non solo al costo.', 'Acknowledge the competing consideration.', 'Friends want to drive tired because the hotel is booked.', 'Acknowledge the booking but suggest resting before continuing.', 'Capisco la prenotazione, ma prima di ripartire sarebbe meglio riposarci.'],
  ['E che cosa facciamo tutto il giorno?', 'Propose an indoor visit now and moving the outdoor activity to tomorrow if possible.', 'Potremmo visitare il museo oggi e spostare l’escursione a domani, se c’è posto.', 'Offer an alternative, not only an objection.', 'A train strike disrupts a day trip.', 'Suggest visiting somewhere nearby and rescheduling the longer journey.', 'Oggi potremmo restare in zona e rimandare il viaggio più lungo.'],
  ['Qualcuno però vuole partire subito.', 'Suggest agreeing a meeting point so people can choose different activities.', 'Potremmo fissare un punto di ritrovo e lasciare che ciascuno scelga come passare la mattina.', 'Allow different preferences without losing coordination.', 'Your group disagrees about a long city walk.', 'Suggest splitting up and meeting for dinner at an agreed time.', 'Dividiamoci e ritroviamoci per cena a un’ora concordata.'],
])
episode('B2', 'home', 'A project over budget', 'Negotiate scope, costs and expectations in a practical project.', ['conditional', 'passive', 'time clauses'], 'A builder explains that a renovation will cost more than planned.', [
  ['Sono emersi dei lavori in più.', 'Ask which work is essential and which is optional.', 'Quali interventi sono indispensabili e quali possiamo scegliere di rimandare?', 'Separate needs from preferences.', 'A gardener proposes several extra tasks.', 'Ask which are urgent and which can wait until next season.', 'Quali lavori sono urgenti e quali possono aspettare la prossima stagione?'],
  ['Il materiale scelto costa molto di più.', 'Ask for a cheaper alternative that preserves the main appearance.', 'Ci sarebbe un’alternativa meno costosa che mantenga più o meno lo stesso aspetto?', 'Keep the goal while relaxing one constraint.', 'A kitchen quote exceeds your budget.', 'Ask which changes would reduce cost without reducing storage.', 'Quali modifiche ridurrebbero il prezzo senza farci perdere spazio?'],
  ['Cominciamo e poi facciamo i conti.', 'Say you want an agreed written estimate before further work starts.', 'Prima di procedere, vorrei concordare un preventivo scritto per i lavori aggiuntivi.', 'Firm, practical, courteous.', 'A supplier wants verbal approval for extras.', 'Ask for a revised quotation before approving them.', 'Prima di approvarli, vorrei ricevere il preventivo aggiornato.'],
])
episode('B2', 'health', 'Discuss options clearly', 'Explain priorities and ask balanced questions about options.', ['indirect questions', 'conditional', 'comparison'], 'You discuss options with a health professional; do not invent clinical advice.', [
  ['Qual è il suo obiettivo principale?', 'Say maintaining everyday mobility matters more to you than a quick result.', 'Per me conta soprattutto mantenere la mobilità nella vita quotidiana, più che ottenere un risultato rapido.', 'State your own priorities.', 'A professional asks what matters in a recovery plan.', 'Say independence at home is your main priority.', 'La mia priorità è riuscire a essere autonomo a casa.'],
  ['Ci sono due possibilità.', 'Ask about benefits, drawbacks and what happens if you wait.', 'Potrebbe spiegarmi vantaggi, svantaggi e che cosa comporterebbe aspettare?', 'Ask for comparison, not a recommendation from the exercise.', 'You are offered two appointment pathways.', 'Ask how waiting times and follow-up differ.', 'Come cambiano i tempi di attesa e i controlli successivi?'],
  ['Mi sembra tutto chiaro.', 'Say you understand the main idea but want to summarise it to check.', 'Credo di aver capito il punto principale. Posso riassumerlo per verificare?', 'Use a teach-back request.', 'You receive complex rehabilitation instructions.', 'Ask to repeat the plan in your own words to check understanding.', 'Posso ripetere il programma con parole mie per essere sicuro di aver capito?'],
])
episode('B2', 'work', 'Disagree constructively', 'Challenge a proposal, offer an alternative and agree a trial.', ['concession', 'conditional', 'hypothetical'], 'Your group is choosing a new way to organise its work.', [
  ['Dobbiamo cambiare tutto da lunedì.', 'Acknowledge the need for change but question the proposed speed.', 'Sono d’accordo che serva un cambiamento, ma passare a tutto lunedì mi sembra troppo rapido.', 'Separate the objective from the implementation.', 'A class wants to replace every lesson with independent study.', 'Support independence but question removing all shared practice.', 'L’autonomia è importante, ma eliminare tutta la pratica insieme mi sembra eccessivo.'],
  ['Non possiamo continuare a rimandare.', 'Propose testing the new system with one team for two weeks.', 'Potremmo provarlo con un solo gruppo per due settimane, invece di rimandare o cambiare tutto subito.', 'Offer a concrete middle path.', 'A club must choose a new booking system.', 'Suggest a limited trial before asking everyone to use it.', 'Facciamo una prova limitata prima di farlo usare a tutti.'],
  ['Come sapremo se funziona?', 'Suggest comparing completion time and user problems before deciding.', 'Confrontiamo i tempi e i problemi segnalati dagli utenti, poi decidiamo se estenderlo.', 'Define evidence before declaring success.', 'A group tests a new meeting format.', 'Suggest reviewing participation and usefulness after three meetings.', 'Dopo tre incontri valutiamo quante persone partecipano e quanto lo trovano utile.'],
])
episode('B2', 'culture', 'Defend an interpretation', 'Support an interpretation and engage with another reading.', ['opinion', 'concession', 'hypothesis'], 'Your book group disagrees about a character’s decision.', [
  ['Il protagonista è semplicemente egoista.', 'Suggest fear also explains his behaviour, referring to his refusal to speak.', 'Secondo me c’entra anche la paura: il fatto che non riesca a parlarne lo fa pensare.', 'Offer an interpretation with evidence.', 'A film character seems cold.', 'Suggest their silence may show grief rather than indifference.', 'Il silenzio potrebbe esprimere dolore, non necessariamente indifferenza.'],
  ['Ma abbandona gli altri proprio quando serve.', 'Accept the criticism while distinguishing explanation from excuse.', 'È vero, e non voglio giustificarlo; sto cercando di capire perché lo faccia.', 'Understanding is not the same as endorsing.', 'A group criticises an artist’s behaviour.', 'Say the historical context helps explain it but does not excuse it.', 'Il contesto storico aiuta a spiegarlo, ma non lo rende giustificabile.'],
  ['Il finale allora ti sembra riuscito?', 'Give your own view of an ambiguous ending and explain what it does for you as a reader.', 'Sì, proprio perché non risolve tutto e lascia al lettore il compito di giudicare.', 'Link a technique to its effect.', 'A friend dislikes an unresolved film ending.', 'Explain why you find the uncertainty thought-provoking.', 'L’incertezza mi sembra interessante perché mi costringe a ripensare a quello che ho visto.'],
])
episode('B2', 'community', 'Balance different needs', 'Discuss a local proposal fairly and seek a workable compromise.', ['concession', 'conditional', 'cause and consequence'], 'Residents debate evening events in a shared hall.', [
  ['Gli eventi portano solo rumore.', 'Acknowledge noise while pointing out social and financial benefits.', 'Il rumore è un problema reale, ma gli eventi creano occasioni d’incontro e aiutano a finanziare la sala.', 'Represent more than one interest.', 'A town debates pedestrianising a street.', 'Acknowledge delivery problems while mentioning safety benefits.', 'Le consegne vanno organizzate, ma una strada pedonale può essere più sicura.'],
  ['Quindi dobbiamo sopportare tutto?', 'Propose a finishing time and limits on amplified music.', 'No: potremmo concordare un orario di chiusura e limiti alla musica amplificata.', 'Move from opposing positions to conditions.', 'Residents worry about outdoor café tables.', 'Suggest preserving a clear accessible path and limiting hours.', 'Potremmo lasciare libero un passaggio accessibile e fissare degli orari.'],
  ['E se gli accordi non vengono rispettati?', 'Suggest a trial period with a contact person and a review date.', 'Facciamo una prova con un referente per le segnalazioni e una data per valutare i risultati.', 'Build accountability into the compromise.', 'A new parking arrangement worries neighbours.', 'Suggest reviewing it after a month using residents’ feedback.', 'Rivediamolo dopo un mese, raccogliendo le osservazioni dei residenti.'],
])
episode('B2', 'mediation', 'Reconcile two accounts', 'Separate shared facts from differing interpretations.', ['reported speech', 'contrast', 'summarising'], 'Two volunteers disagree about why an event started late.', [
  ['La sala era pronta alle sei. — Sì, ma mancavano i microfoni.', 'Summarise what both agree on and what remained unfinished.', 'La sala era pronta alle sei, ma l’attrezzatura audio non era ancora completa.', 'Keep the two facts compatible.', 'One person says a report was delivered; another says pages were missing.', 'Explain the common ground and remaining problem.', 'Il rapporto è arrivato, ma non era completo.'],
  ['Quindi è tutta colpa loro!', 'Avoid assigning blame and suggest checking who was responsible for the sound.', 'Prima di attribuire la colpa, verificherei chi doveva occuparsi dell’audio.', 'Identify missing information.', 'A delivery arrived late and two departments blame each other.', 'Suggest checking the agreed handover before deciding responsibility.', 'Controlliamo prima come era stato concordato il passaggio di consegne.'],
  ['Che cosa diciamo al resto del gruppo?', 'Give a brief neutral summary and propose a clearer checklist next time.', 'L’avvio è stato ritardato da un problema con l’audio. Per la prossima volta prepariamo una lista chiara delle responsabilità.', 'Summary plus practical learning.', 'A meeting link was sent without a password.', 'Explain the problem neutrally and suggest checking both together next time.', 'Mancava la password nel messaggio; la prossima volta controlliamo insieme link e accesso.'],
])

// C1: pragmatic meaning, nuanced register and precision under competing demands.
episode('C1', 'social', 'Hear the worry beneath the words', 'Recognise an implied concern and respond with tact without making assumptions.', ['subjunctive', 'hedging', 'pragmatic reformulation'], 'A friend feels left out of a shared project.', [
  ['Tranquilli, tanto ormai decidete sempre tutto voi.', 'Acknowledge that they may feel excluded, without accusing them of overreacting.', 'Mi sembra che tu ti sia sentito escluso dalle decisioni. Mi dispiace: vorrei capire meglio che cosa è successo.', 'Name a possible feeling tentatively.', 'A colleague says, “Fate pure, il mio parere evidentemente non serve”.', 'Acknowledge the implied frustration and invite their view.', 'Mi pare che tu senta che il tuo contributo non venga ascoltato. Vorrei invece capire che cosa proponi.'],
  ['Non voglio che mi coinvolgiate solo per educazione.', 'Distinguish a genuine role in decisions from a token invitation.', 'Hai ragione a chiedere un coinvolgimento reale: possiamo decidere insieme quali scelte sono ancora aperte, non limitarci ad aggiornarti.', 'Offer influence, not merely reassurance.', 'A volunteer feels invited only to carry out others’ plans.', 'Propose involving them while plans are still being shaped.', 'Vorrei coinvolgerti quando le proposte sono ancora modificabili, non solo quando c’è da eseguirle.'],
  ['Forse sono stato un po’ brusco.', 'Accept the repair warmly while keeping the underlying issue worth discussing.', 'Capisco perché ti sia uscito così. Lasciamo perdere il tono, ma non il problema che hai sollevato.', 'Repair the relationship without erasing the concern.', 'A friend apologises for complaining sharply about unequal hosting duties.', 'Accept the apology and suggest discussing a fairer arrangement.', 'Grazie per averlo detto. Non serve scusarti per sollevare il problema: troviamo un modo più equo di dividerci il lavoro.'],
])
episode('C1', 'questions', 'Ask the question that matters', 'Distinguish vague reassurance from a testable claim and seek clarification tactfully.', ['epistemic modality', 'indirect questions', 'conditional framing'], 'A project presentation contains reassuring but imprecise claims.', [
  ['Il nuovo sistema sarà molto più efficiente.', 'Ask what “efficient” means here: less time, lower cost or better outcomes.', 'Quando dice “più efficiente”, si riferisce ai tempi, ai costi o alla qualità dei risultati?', 'Unpack the term before challenging it.', 'An organiser calls a course “more accessible”.', 'Ask whether that means price, physical access or ease of understanding.', 'Per “più accessibile” intende il prezzo, l’accesso fisico o la facilità di comprensione?'],
  ['Abbiamo motivo di essere ottimisti.', 'Ask which evidence supports confidence and what remains uncertain.', 'Quali elementi giustificano questo ottimismo e su quali aspetti rimane invece incertezza?', 'Request both support and limits.', 'A provider says a new service is reliable.', 'Ask what has been tested and what has not yet been tried.', 'Quali aspetti avete già verificato e quali devono ancora essere messi alla prova?'],
  ['Non si fida del nostro giudizio?', 'Reframe your questions as a way to make a shared decision accountable, not a personal challenge.', 'Non metto in dubbio la vostra competenza; vorrei rendere espliciti i criteri su cui prenderemo insieme la decisione.', 'Protect the relationship while retaining the question.', 'A speaker treats your request for sources as hostility.', 'Explain that shared evidence helps everyone assess the proposal.', 'Chiedo le fonti perché una base comune ci permette di valutare la proposta, non per mettere in discussione la sua buona fede.'],
])
episode('C1', 'routines', 'Talk about change without clichés', 'Express mixed feelings and qualify a personal narrative.', ['concession', 'counterfactual', 'discourse organisation'], 'You reflect on a major change in your everyday life.', [
  ['Hai finalmente trovato l’equilibrio perfetto?', 'Reject the idea of a final perfect balance while recognising real improvement.', 'Più che un equilibrio definitivo, ho trovato un modo migliore di accorgermi quando sto esagerando.', 'Reframe an over-simple label.', 'Someone calls your move a completely fresh start.', 'Explain that it opened possibilities but did not erase old habits.', 'Mi ha aperto nuove possibilità, ma non ha cancellato automaticamente le abitudini di prima.'],
  ['Allora bastava avere più tempo libero.', 'Explain that freedom also required learning to choose and refuse things.', 'Il tempo libero da solo non bastava: ho dovuto imparare a scegliere e, soprattutto, a dire di no senza sentirmi in colpa.', 'Explain the mechanism behind the change.', 'Someone assumes better equipment solved a creative block.', 'Explain that changing your working habits mattered more.', 'L’attrezzatura ha aiutato, ma la differenza l’ha fatta il modo in cui ho riorganizzato il lavoro.'],
  ['Se potessi tornare indietro, cambieresti tutto?', 'Offer a nuanced answer: change some choices but recognise what you learnt from them.', 'Cambierei alcune scelte, ma non vorrei cancellare anche ciò che mi hanno insegnato.', 'Avoid an all-or-nothing answer.', 'Someone asks whether you regret a demanding project.', 'Acknowledge the cost while valuing the skills it developed.', 'Non lo rifarei allo stesso modo, ma riconosco quanto mi abbia insegnato.'],
])
episode('C1', 'food', 'Culture around the table', 'Navigate cultural expectations and personal boundaries tactfully.', ['register', 'concession', 'indirect refusal'], 'At a dinner, a host interprets refusing more food as rejection.', [
  ['Non ne vuoi ancora? Non ti è piaciuto?', 'Reassure the host specifically, while declining another portion.', 'Mi è piaciuto molto, soprattutto il condimento; semplicemente sono sazio e preferisco fermarmi qui.', 'Appreciation and refusal can coexist.', 'A host insists on pouring more wine.', 'Thank them warmly but clearly decline more.', 'Ti ringrazio, è stato ottimo, ma per stasera mi fermo qui.'],
  ['Da noi si insiste: è un modo per dimostrare affetto.', 'Acknowledge the intention while explaining that accepting a no can also show care.', 'Capisco il gesto affettuoso; per me è premuroso anche accettare che una persona dica di no senza dover insistere.', 'Discuss different conventions without ranking cultures.', 'A friend says generous hosts must always serve too much.', 'Acknowledge generosity and suggest offering choice can express it too.', 'La generosità conta, ma può esprimersi anche lasciando agli ospiti la libertà di scegliere.'],
  ['Allora come faccio a non sembrare freddo?', 'Suggest a warm offer with permission to decline and an invitation to take food home.', 'Puoi offrire con calore, aggiungere che non c’è alcun obbligo e proporre di portarne un po’ a casa.', 'Offer a practical wording strategy.', 'A host worries about accommodating dietary preferences.', 'Suggest asking privately beforehand rather than drawing attention at dinner.', 'Chiederei prima in privato, così puoi accogliere le preferenze senza mettere nessuno al centro dell’attenzione.'],
])
episode('C1', 'shopping', 'Separate goodwill from responsibility', 'Handle a formal complaint with precision and proportionate tone.', ['formal register', 'concession', 'conditional remedies'], 'A supplier describes correcting an incomplete order as a special favour.', [
  ['In via del tutto eccezionale, completeremo la consegna.', 'Thank them for acting while clarifying that completing the agreed order is the issue.', 'Apprezzo che interveniate; vorrei però precisare che si tratta di completare quanto era stato concordato, non di una richiesta aggiuntiva.', 'Acknowledge action without accepting the framing.', 'A service provider calls correcting their invoice a concession.', 'Clarify that you are asking for the agreed price to be reflected accurately.', 'Vi ringrazio della verifica; chiedo semplicemente che la fattura riporti il prezzo concordato.'],
  ['Possiamo darle un buono, così chiudiamo la questione.', 'Explain that a voucher does not address your need and request the missing item or repayment for it.', 'Il buono non risolve il problema concreto: preferirei ricevere l’articolo mancante oppure il rimborso del suo costo.', 'Keep the remedy linked to the problem.', 'A hotel offers future credit after an unavailable paid service.', 'Explain why future credit may not be usable and ask for another solution.', 'Non so se potrò tornare, quindi il credito futuro potrebbe non essermi utile. Possiamo concordare un’altra soluzione?'],
  ['Mi sta accusando di essere scorretto?', 'Separate the disputed process from personal intent and restate the desired outcome.', 'Non sto attribuendo intenzioni personali; sto cercando di chiarire quanto manca e come completare correttamente l’ordine.', 'De-escalate without abandoning the substance.', 'A contractor takes a query about delays personally.', 'Explain that you want a realistic plan, not to judge their motives.', 'Non voglio discutere delle intenzioni; mi serve un programma realistico su cui organizzarmi.'],
])
episode('C1', 'travel', 'Make a group decision under uncertainty', 'Compare uncertain options and communicate a provisional decision.', ['probability', 'conditional scenarios', 'concession'], 'A transport disruption leaves your group with incomplete information.', [
  ['Dicono che il treno forse partirà, ma nessuno sa quando.', 'Distinguish a possibility from a usable plan and ask for a latest decision time.', 'Che possa partire è possibile, ma non è ancora un piano su cui contare. Entro che ora dobbiamo scegliere l’alternativa?', 'Separate possibility from practical reliability.', 'A ferry may sail if the wind drops.', 'Ask when a firm update is expected before arranging another route.', 'Quando è previsto un aggiornamento affidabile? Ci serve per decidere se cercare un’altra strada.'],
  ['Il taxi costa di più, ma ci porta sicuramente in tempo.', 'Ask whether arrival is actually guaranteed and compare the extra cost with the consequences of delay.', 'L’arrivo è davvero garantito? Valuterei il costo in più rispetto a quello che perderemmo arrivando tardi.', 'Question certainty and compare consequences.', 'A group considers paying for a faster flight connection.', 'Ask how much risk it removes and whether the connection is protected.', 'Quanto riduce davvero il rischio? E la coincidenza sarebbe garantita?'],
  ['Decidi tu, allora.', 'Propose waiting thirty minutes, with an agreed fallback if no firm update arrives.', 'Aspetterei ancora mezz’ora; se non arriva una conferma, prendiamo l’alternativa su cui ci siamo accordati.', 'Make a conditional decision and clear trigger.', 'A weather-dependent visit remains uncertain.', 'Set a time to switch to the indoor plan if conditions remain unclear.', 'Se entro mezzogiorno non abbiamo indicazioni chiare, passiamo al programma al coperto.'],
])
episode('C1', 'home', 'Preserve intent while changing design', 'Negotiate design choices by distinguishing goals from particular solutions.', ['concession', 'subjunctive', 'comparative evaluation'], 'You discuss a home project with a designer and another resident.', [
  ['Se togliamo questa parete, sembrerà tutto più moderno.', 'Explain that openness matters to you, but a modern appearance is not the main goal.', 'Mi interessa rendere lo spazio più aperto, ma non necessariamente dargli un aspetto moderno.', 'Distinguish the desired effect from the style.', 'A designer proposes a very bright garden scheme.', 'Explain that visibility matters but you also want to preserve a quiet atmosphere.', 'Voglio vedere bene, ma vorrei conservare un’atmosfera raccolta, non illuminare tutto allo stesso modo.'],
  ['L’alternativa è meno spettacolare.', 'Argue that a quieter solution may serve daily use better while preserving character.', 'Può essere meno d’effetto, ma forse risponde meglio all’uso quotidiano e rispetta di più il carattere della casa.', 'Compare practical and aesthetic criteria.', 'A kitchen design has an impressive island but little circulation space.', 'Say visual impact should not compromise moving around comfortably.', 'L’effetto visivo non dovrebbe andare a scapito della comodità negli spostamenti.'],
  ['Non possiamo soddisfare tutte le richieste.', 'Suggest ranking essentials and preferences before choosing a compromise.', 'Allora distinguiamo i requisiti irrinunciabili dalle preferenze, così il compromesso sarà consapevole.', 'Make trade-offs explicit.', 'Two people disagree about a garden layout.', 'Suggest agreeing first on the activities the garden must support.', 'Prima concordiamo quali attività deve permettere il giardino; poi confrontiamo le soluzioni.'],
])
episode('C1', 'health', 'Express uncertainty without losing your voice', 'Discuss incomplete understanding and communicate preferences precisely.', ['epistemic expressions', 'conditional', 'reformulation'], 'You are preparing questions for a complex health discussion, not seeking clinical advice here.', [
  ['Ha letto qualcosa e si è già fatto un’idea?', 'Say you have read different accounts but do not know how well they apply to your situation.', 'Ho letto esperienze diverse, ma non so quanto siano confrontabili con la mia situazione.', 'Distinguish reading from applicable evidence.', 'You have seen conflicting recovery stories online.', 'Say they helped you form questions but not a firm conclusion.', 'Mi hanno aiutato a formulare delle domande, ma non a trarre una conclusione affidabile.'],
  ['Quale risultato considererebbe accettabile?', 'Explain that a modest improvement with fewer disruptions may suit you better than an ambitious but burdensome option.', 'Potrei preferire un miglioramento più limitato, ma compatibile con la mia vita quotidiana, a un percorso più impegnativo.', 'Express a value trade-off without prescribing an option.', 'A professional asks about scheduling a long programme.', 'Explain that caring responsibilities affect what you can realistically manage.', 'Devo tenere conto anche delle responsabilità familiari, quindi vorrei valutare un programma sostenibile.'],
  ['Le probabilità non permettono certezze.', 'Acknowledge uncertainty and ask what information would help you decide anyway.', 'Capisco che non ci siano certezze. Quali informazioni ci aiuterebbero comunque a scegliere in modo consapevole?', 'Seek a process for decision-making under uncertainty.', 'Two reasonable options remain after a consultation.', 'Ask which differences matter most for your stated priorities.', 'Quali differenze dovrei considerare soprattutto, tenendo presenti le priorità che le ho descritto?'],
])
episode('C1', 'work', 'Give difficult feedback usefully', 'Separate behaviour from identity and agree a constructive next step.', ['reported observations', 'conditional', 'purpose'], 'You need to discuss a colleague’s contribution to a group meeting.', [
  ['Mi sembra che tu non abbia apprezzato il mio intervento.', 'Say the ideas were useful but repeated interruptions prevented others from contributing.', 'Le idee erano utili; il problema è che le interruzioni hanno lasciato poco spazio agli altri.', 'Describe an observable behaviour and its impact.', 'A volunteer gives a long introduction at every event.', 'Acknowledge their enthusiasm and explain that it reduces participation time.', 'Apprezzo l’entusiasmo, ma introduzioni così lunghe riducono il tempo in cui gli altri possono partecipare.'],
  ['Quindi dovrei stare zitto?', 'Reject that interpretation and suggest shorter contributions followed by questions.', 'Al contrario, vorrei che il tuo contributo arrivasse meglio: interventi più brevi, seguiti da una domanda, potrebbero aprire la discussione.', 'Make a positive, usable alternative.', 'A writer thinks feedback means removing their distinctive voice.', 'Explain you want clearer structure while preserving their voice.', 'Non vorrei togliere la tua voce, ma darle una struttura che permetta al lettore di seguirla meglio.'],
  ['Come facciamo a capire se cambia qualcosa?', 'Agree one observable behaviour to try and a private review afterwards.', 'Nel prossimo incontro proviamo a lasciare finire ogni intervento; poi ne parliamo in privato e vediamo come è andata.', 'Use a limited experiment, not a global judgement.', 'A teacher wants to reduce over-explaining.', 'Suggest a short explanation followed by learner practice and review of the effect.', 'Prova una spiegazione breve seguita subito dalla pratica; poi valuta che cosa gli allievi riescono a fare.'],
])
episode('C1', 'culture', 'Read between the lines', 'Interpret tone, narrative perspective and ambiguity with textual support.', ['inference', 'subjunctive', 'nuanced comparison'], 'A reading group discusses the sentence “Naturalmente, lui aveva sempre ragione”, spoken by an irritated narrator.', [
  ['È una frase di ammirazione?', 'Explain that the context makes it sound ironic rather than admiring.', 'In questo contesto “naturalmente” suona ironico: il narratore sembra irritato dall’idea che lui debba avere sempre ragione.', 'Ground the inference in context and wording.', 'A character says “Che splendida idea” after a plan fails.', 'Explain why the praise may be sarcastic.', 'Dopo il fallimento, quelle parole sembrano un rimprovero ironico, non un elogio sincero.'],
  ['Possiamo fidarci del narratore?', 'Distinguish an emotionally biased account from deliberate lying.', 'Può essere condizionato dal risentimento senza mentire deliberatamente: la sua prospettiva è parziale.', 'Avoid collapsing different explanations.', 'A memoir describes a childhood rival unkindly.', 'Explain why selective memory does not automatically imply fabrication.', 'Il ricordo può essere selettivo senza essere inventato; bisogna distinguere prospettiva e falsificazione.'],
  ['Allora qual è l’interpretazione giusta?', 'Argue for comparing readings against details rather than insisting on one unsupported answer.', 'Confronterei le letture con i dettagli del testo: non tutte hanno lo stesso sostegno, anche se più di una resta plausibile.', 'Allow plurality without saying every reading is equal.', 'A group debates an abstract painting.', 'Suggest distinguishing visible evidence from personal association.', 'Proverei a separare quello che osserviamo nell’opera dalle associazioni personali che ci suscita.'],
])
episode('C1', 'community', 'Lead a fair discussion', 'Make competing values explicit and invite overlooked perspectives.', ['nominalisation', 'concession', 'facilitation language'], 'A community meeting considers renting a public room to a commercial organiser.', [
  ['Se paga bene, non vedo il problema.', 'Explain that income is one criterion alongside access for local users.', 'Il ricavo è un criterio importante, ma va messo accanto all’accesso per chi usa abitualmente lo spazio.', 'Name the competing value.', 'A council proposes closing a quiet library branch.', 'Explain that low visitor numbers do not capture its value to isolated users.', 'Il numero degli accessi non descrive da solo il valore del servizio per le persone più isolate.'],
  ['Qui siamo tutti d’accordo.', 'Point out that people unable to attend may have different needs and suggest consulting them.', 'Tra i presenti forse sì; chi non è potuto venire potrebbe avere esigenze diverse. Prima di concludere, sentirei anche loro.', 'Distinguish attendance from representation.', 'An online survey is treated as everyone’s opinion.', 'Mention those who cannot use the survey and suggest another channel.', 'Chi non usa il sito rischia di restare escluso; offrirei anche un modo diverso per esprimersi.'],
  ['Non possiamo continuare a discutere all’infinito.', 'Propose a deadline, published criteria and a reviewable trial.', 'Fissiamo una scadenza, rendiamo chiari i criteri e decidiamo una prova che possa essere rivista.', 'Combine participation with a decision process.', 'A local group is divided about a new timetable.', 'Suggest a limited trial with agreed measures and a review date.', 'Facciamo una prova a tempo, con indicatori concordati e una data precisa per il riesame.'],
])
episode('C1', 'mediation', 'Translate expertise into useful language', 'Reformulate complex information without losing important qualifications.', ['reported meaning', 'qualification', 'audience adaptation'], 'You help a group understand a technical project update.', [
  ['Il campione è ridotto: il risultato suggerisce un miglioramento, ma non consente generalizzazioni.', 'Explain this in everyday language, preserving the uncertainty.', 'Abbiamo osservato un possibile miglioramento in poche persone, ma non possiamo ancora dire che valga per tutti.', 'Simpler language must keep the limitation.', 'A report says early satisfaction data are encouraging but selection bias is possible.', 'Explain that volunteers may not represent all users.', 'I primi commenti sono positivi, ma chi ha scelto di partecipare potrebbe essere diverso dagli altri utenti.'],
  ['Quindi il progetto non serve a niente?', 'Correct that inference: promising early evidence is different from either proof or failure.', 'Non è questo: ci sono segnali promettenti, ma sono ancora troppo limitati per una conclusione definitiva.', 'Reject the false choice.', 'A trial fails to show a clear advantage.', 'Explain that this does not by itself prove the two options are identical.', 'Non aver trovato un vantaggio chiaro non dimostra automaticamente che le due opzioni siano identiche.'],
  ['Come lo raccontiamo ai volontari senza scoraggiarli?', 'Give an encouraging but honest two-sentence summary and explain the next step.', 'Il vostro contributo ha fatto emergere segnali interessanti. Ora dobbiamo verificarli con più persone e in situazioni diverse.', 'Encouragement and accuracy belong together.', 'A pilot lesson has useful but mixed feedback.', 'Summarise progress while inviting further testing.', 'Abbiamo capito che cosa funziona meglio e che cosa va cambiato. Proviamo le modifiche con un altro gruppo prima di estenderle.'],
])

// C2: flexible control, implicit meaning, synthesis and register. Not accent imitation.
episode('C2', 'social', 'Repair without surrendering your point', 'Respond to face-threatening implications with empathy, precision and appropriate informality.', ['pragmatic inference', 'register shifts', 'counterfactual qualification'], 'A close friend is hurt after a disagreement about a shared commitment.', [
  ['Figurati, fai pure come ti pare. Come sempre.', 'Respond to the hurt beneath the apparent permission; do not treat it as genuine agreement.', 'Da come lo dici, mi sembra che tu ti senta messo da parte. Prima di decidere vorrei capire quale parte dell’accordo senti che non ho rispettato.', 'Distinguish literal permission from implied protest.', 'A friend says “Non disturbarti, ormai ci sono abituato” after you cancel.', 'Acknowledge the pattern they imply and invite a concrete discussion.', 'Mi sembra che non sia solo questa volta a pesarti. Vorrei capire quando ti sei sentito trascurato, senza liquidare la cosa con una scusa.'],
  ['Se ci tenessi davvero, non avresti bisogno che te lo spiegassi.', 'Affirm care while gently rejecting mind-reading as a fair test of the relationship.', 'Ci tengo, ed è proprio per questo che te lo chiedo. Capire da solo ogni aspettativa non è sempre possibile; parlarne non rende meno autentico il rapporto.', 'Reject the premise without dismissing the emotion.', 'A partner equates disagreement with disloyalty.', 'Affirm commitment while defending room for a different judgement.', 'Essere dalla tua parte non significa dover condividere ogni valutazione; vorrei poterti dire sinceramente anche quando vedo le cose in modo diverso.'],
  ['Va bene. Forse possiamo ricominciare.', 'Offer a warm, natural repair and one specific change you would genuinely be willing to make.', 'Sì, mi farebbe piacere. Da parte mia, ti avviserò prima quando un impegno comune rischia di cambiare.', 'Choose your own credible commitment; do not overpromise.', 'A friend agrees to reset expectations after a misunderstanding.', 'Offer a concrete change that fits your own way of maintaining friendships.', 'Volentieri. Preferisco prometterti meno e rispettarlo: fissiamo un momento in cui sentirci con calma.'],
])
episode('C2', 'questions', 'Expose a false choice without derailing', 'Question loaded premises and reformulate a discussion productively.', ['rhetorical framing', 'epistemic precision', 'hypothetical reasoning'], 'A public discussion is being reduced to slogans.', [
  ['Siete favorevoli al progresso o volete lasciare tutto com’è?', 'Reject the false choice while making space for evaluating the actual proposal.', 'La scelta non è tra progresso e immobilismo: possiamo condividere l’obiettivo e discutere se questa proposta sia il modo migliore per raggiungerlo.', 'Expose the framing, then restore the real question.', 'Someone asks whether you support safety or personal freedom.', 'Explain that the practical question is how to balance the two in this case.', 'Non sceglierei uno dei due valori in astratto: discuterei quali limiti siano proporzionati in questa situazione.'],
  ['Ma non c’è alcuna prova che possa andare male.', 'Distinguish lack of evidence of harm from evidence that harm is unlikely, without predicting disaster.', 'L’assenza di prove di un danno non equivale a una prova di sicurezza. Non significa che andrà male, ma che dobbiamo chiarire che cosa sappiamo davvero.', 'Do not turn uncertainty into a contrary certainty.', 'A proposal is called effective because nobody has disproved it.', 'Explain why effectiveness still needs positive evidence.', 'Il fatto che non sia stato smentito non ne dimostra l’efficacia: servono elementi che sostengano il risultato atteso.'],
  ['Che cosa potrebbe farti cambiare idea?', 'Choose a position on trying a new local service and specify evidence that would genuinely change your judgement.', 'Sarei favorevole a una prova; cambierei idea se i dati mostrassero che esclude proprio gli utenti a cui dovrebbe servire.', 'Choose your own position and a real revision condition.', 'A discussion concerns replacing face-to-face classes with online lessons.', 'State your own provisional view and what evidence could alter it.', 'Non le sostituirei del tutto, ma rivedrei la mia posizione se gli allievi meno autonomi partecipassero e progredissero altrettanto bene.'],
])
episode('C2', 'routines', 'Tell a layered personal story', 'Build a coherent account with perspective, qualification and a meaningful ending.', ['narrative aspect', 'retrospective perspective', 'ellipsis'], 'You are asked to reflect on an experience that changed how you use your time.', [
  ['Raccontami una scelta che, col tempo, hai visto diversamente.', 'Give a real or plausible example: contrast how it felt then with how you understand it now.', 'Quando ho lasciato quell’impegno mi sembrava una rinuncia; a distanza di tempo, lo vedo come il momento in cui ho cominciato a scegliere con più attenzione.', 'Your own experience or an invented one is welcome.', 'A friend asks about a creative project you abandoned.', 'Explain how your interpretation of stopping has changed over time.', 'Allora lo consideravo un fallimento; ora penso che fermarmi mi abbia permesso di capire quale parte del progetto mi interessava davvero.'],
  ['Quindi era tutto inevitabile?', 'Resist hindsight bias: explain that the outcome makes the story look tidier than the choices felt.', 'A raccontarlo adesso sembra lineare, ma sul momento non lo era affatto: c’erano alternative ragionevoli e parecchia incertezza.', 'Distinguish the polished story from lived uncertainty.', 'Someone calls your current career path an obvious destiny.', 'Explain that it emerged from contingent decisions rather than a fixed plan.', 'Oggi si vede un filo, ma molte scelte sono nate da occasioni impreviste, non da un piano già chiaro.'],
  ['Che cosa ti porti dietro di quell’esperienza?', 'End with a personal insight and a limitation, avoiding a universal slogan.', 'Per me è stato utile imparare a lasciare spazio, ma non ne ricaverei una regola per tutti: dipende da ciò a cui si rinuncia e da ciò che si protegge.', 'Offer insight without pretending it applies universally.', 'A listener asks what a difficult journey taught you.', 'Offer your own lesson while acknowledging it may not suit every situation.', 'Ho imparato a chiedere aiuto prima, anche se so che non sempre ci sono persone o risorse disponibili.'],
])
episode('C2', 'food', 'Humour, identity and hospitality', 'Handle teasing and cultural claims without losing warmth or nuance.', ['irony', 'register', 'concession and qualification'], 'Friends discuss food traditions over dinner.', [
  ['Ah, metti il latte nel tè: ormai dobbiamo ritirarti il passaporto italiano!', 'Respond playfully to the teasing without taking the claim literally or insulting anyone.', 'Allora mi toccherà chiedere asilo al reparto biscotti! Sul tè resto diplomaticamente britannico.', 'A light, good-natured reply; many versions work.', 'A friend jokes that your unusual pizza topping is a diplomatic incident.', 'Reply with gentle humour that shows you understand the joke.', 'Prometto che non la presenterò come ricetta tradizionale: evitiamo almeno la crisi internazionale.'],
  ['Scherzi a parte, le ricette autentiche non si cambiano.', 'Give your own nuanced view of tradition and adaptation, acknowledging a reason for each.', 'Capisco il valore di conservare una ricetta riconoscibile; allo stesso tempo, molte tradizioni sono nate proprio da adattamenti. Distinguerei tra reinterpretarla e spacciarla per l’originale.', 'Take your own position, with a fair concession.', 'A group debates changing a traditional festival.', 'Offer your own view while distinguishing continuity from immobility.', 'Conserverei gli elementi che danno senso alla festa, senza pensare che ogni dettaglio debba restare identico per sempre.'],
  ['La battuta di prima ti ha dato fastidio?', 'Explain that the friendly intention was clear, while noting that the same joke could land differently with a stranger.', 'Tra noi ho colto il tono affettuoso; con qualcuno che non conosci bene, la stessa battuta potrebbe sembrare un modo per escluderlo.', 'Explain how relationship changes meaning.', 'A friend asks whether teasing about an accent is always harmless.', 'Distinguish shared joking from making someone feel exposed.', 'Dipende dal rapporto e da come la vive l’altra persona: ridere insieme è diverso dal metterla in imbarazzo.'],
])
episode('C2', 'shopping', 'Reframe an entrenched dispute', 'Produce concise, precise language that moves a dispute towards an actionable agreement.', ['formal pragmatics', 'scope limitation', 'conditional commitments'], 'A long email exchange with a supplier has become defensive.', [
  ['Abbiamo già spiegato più volte che non dipende da noi.', 'Acknowledge their explanation but redirect from blame to what they can actually do next.', 'Ho compreso la vostra posizione sulle cause. Per sbloccare la situazione, vorrei concentrarmi sulle azioni che rientrano ora nelle vostre possibilità.', 'Move from attribution to agency.', 'A travel agent repeatedly blames an external provider.', 'Redirect towards the assistance the agent can still offer.', 'Capisco che il disservizio sia nato altrove; ciò che vorrei chiarire è quale assistenza potete offrirmi adesso.'],
  ['Se accetta questa soluzione, considera chiusa ogni questione?', 'Accept only the specified practical remedy, without making a broader promise you cannot assess.', 'Posso confermare che questa soluzione risponde al problema della consegna; non estenderei però l’accordo a questioni che non abbiamo ancora esaminato.', 'Bound the statement carefully; no legal advice is required.', 'A contractor asks whether one repair resolves every concern.', 'Confirm that it addresses that repair while keeping other listed items separate.', 'Questo intervento risolve il difetto indicato; terrei distinti gli altri punti già segnalati.'],
  ['Ci mandi un riepilogo di quello che propone.', 'Give a two-sentence proposal containing action, deadline and how completion will be confirmed.', 'Propongo che inviate il pezzo mancante entro venerdì e mi comunichiate il tracciamento. Una volta ricevuto e verificato, vi confermerò che questo punto è risolto.', 'Precision matters more than length.', 'A service provider asks for a concise resolution plan.', 'Propose a corrected invoice by Monday and written confirmation after you check it.', 'Inviatemi la fattura corretta entro lunedì. Dopo averla verificata, vi confermerò per iscritto la chiusura di questo punto.'],
])
episode('C2', 'travel', 'Represent a group without erasing differences', 'Speak for a group accurately and adapt register between audiences.', ['reported positions', 'qualification', 'register adaptation'], 'A group must change accommodation after an unexpected closure.', [
  ['Che cosa vuole il vostro gruppo?', 'Represent three needs accurately: some need step-free access, some a quiet room, and everyone needs transport nearby.', 'Per alcuni è indispensabile l’accesso senza gradini, altri hanno soprattutto bisogno di una camera tranquilla; per tutti resta essenziale la vicinanza ai trasporti.', 'Do not turn some people’s needs into everyone’s preferences.', 'A group chooses a restaurant.', 'Represent one allergy requirement, several vegetarian preferences and a shared budget limit.', 'Una persona deve evitare un allergene, alcuni preferiscono piatti vegetariani e tutti dobbiamo restare entro il budget concordato.'],
  ['Abbiamo un albergo più lontano ma molto migliore.', 'Ask what “better” means relative to your stated needs, without dismissing the offer.', 'La ringrazio della proposta. In quali aspetti sarebbe migliore rispetto alle esigenze che le ho indicato, e come compenseremmo la maggiore distanza?', 'Keep evaluation tied to the group’s goals.', 'An organiser offers a more prestigious but inaccessible venue.', 'Acknowledge its quality while checking whether it meets the access requirement.', 'Capisco il valore della sede, ma prima di considerarla vorrei verificare il requisito dell’accessibilità.'],
  ['Che cosa dici agli altri mentre aspettiamo?', 'Switch to an informal, reassuring but honest update that avoids promising a solution.', 'Stiamo valutando due alternative; nessuna è ancora confermata. Vi aggiorno appena sappiamo quale rispetta davvero le esigenze del gruppo.', 'Change register without changing certainty.', 'Your friends await a revised route.', 'Give an informal update distinguishing what is settled from what remains open.', 'La prima parte del viaggio è sistemata; per l’ultima tratta stiamo ancora aspettando conferma. Appena arriva, vi scrivo.'],
])
episode('C2', 'home', 'Resolve a disagreement about character', 'Make subjective criteria discussable and synthesise a design compromise.', ['evaluation language', 'reformulation', 'conditional synthesis'], 'Two people disagree strongly over restoring an old room.', [
  ['Così roviniamo l’anima della casa. — Ma non possiamo vivere in un museo!', 'Reformulate both positions in non-polarising terms.', 'Mi sembra che da una parte si voglia preservare ciò che rende riconoscibile la casa, e dall’altra renderla comoda per la vita di oggi.', 'Translate slogans into legitimate goals.', 'A garden dispute is framed as “wildlife paradise” versus “neglected mess”.', 'Reframe it as habitat value and usable, cared-for space.', 'State cercando sia un ambiente favorevole alla fauna sia uno spazio leggibile e piacevole da usare.'],
  ['Il carattere non si può misurare.', 'Agree it is partly subjective, but suggest naming specific features each person values.', 'Non lo ridurrei a un numero, ma possiamo indicare quali materiali, proporzioni o dettagli ci sembrano irrinunciabili.', 'Subjective need not mean impossible to discuss.', 'A music group disagrees about whether a performance has warmth.', 'Suggest identifying the musical choices that create that impression.', 'Non serve quantificarla, ma possiamo parlare di fraseggio, dinamica e rapporto tra i musicisti.'],
  ['Proponi tu una via d’uscita.', 'Offer your own plausible compromise that protects one valued feature and adapts one practical element.', 'Conserverei i materiali e le aperture principali, ma renderei reversibili gli interventi necessari alla comodità quotidiana.', 'Choose a reasoned compromise, not a universal formula.', 'A historic garden needs easier access.', 'Offer a compromise preserving a valued feature while improving access.', 'Manterrei le aiuole storiche, ma aggiungerei un percorso accessibile che si integri nel disegno senza dominarlo.'],
])
episode('C2', 'health', 'Make complex information personally meaningful', 'Summarise an uncertain discussion without replacing the professional’s judgement.', ['calibrated certainty', 'reported meaning', 'value-sensitive reformulation'], 'You help a family member prepare a summary after a complex consultation; practise language, not treatment selection.', [
  ['Ho sentito solo che “di solito va bene”: allora per me è garantito?', 'Distinguish a general pattern from an individual guarantee with a reassuring, honest tone.', 'È incoraggiante che spesso vada bene, ma questo descrive un andamento generale, non una garanzia per il singolo caso.', 'Do not invent probabilities or outcomes.', 'A relative assumes a common side effect is certain to happen to them.', 'Distinguish a possible or frequent effect from inevitability.', 'Il fatto che possa capitare, o che sia frequente, non significa che capiterà necessariamente a te.'],
  ['Non voglio sembrare difficile facendo altre domande.', 'Explain that asking about how an option fits their priorities supports an informed discussion.', 'Chiedere come un’opzione si concili con ciò che conta per te non è essere difficili: aiuta a rendere la decisione davvero condivisa.', 'Support agency without advising a treatment.', 'A friend worries about admitting they did not understand.', 'Explain that clarifying prevents mistaken agreement and suggest a tactful opening.', 'Meglio chiarire che dare un consenso solo apparente: puoi dire “Vorrei verificare di aver capito bene”.'],
  ['Che cosa scriviamo da portare al prossimo incontro?', 'Propose a concise list separating understood facts, unresolved questions and personal priorities.', 'Dividerei gli appunti in tre parti: ciò che abbiamo capito, ciò che resta da chiarire e le priorità personali da discutere.', 'Organise uncertainty rather than filling it with guesses.', 'A relative receives conflicting explanations from two appointments.', 'Suggest recording the apparent difference and asking for reconciliation, not choosing which is right yourselves.', 'Annotiamo in che cosa sembrano differire le spiegazioni e chiediamo di chiarirle insieme, senza risolvere noi l’incertezza.'],
])
episode('C2', 'work', 'Facilitate disagreement under pressure', 'Surface hidden disagreement and turn abstract consensus into accountable action.', ['pragmatic qualification', 'summarising', 'conditional commitments'], 'You chair a discussion where people appear to agree but mean different things.', [
  ['Siamo tutti d’accordo sulla qualità, quindi possiamo procedere.', 'Point out that agreement on the word may hide different standards and ask for concrete criteria.', 'Condividiamo l’obiettivo, ma forse non ancora il significato operativo di “qualità”. Quali risultati dovremmo osservare per dire che l’abbiamo raggiunta?', 'Turn a shared label into shared criteria.', 'A team claims everyone supports “flexibility”.', 'Ask whether they mean choice of hours, location or responsibilities.', 'Prima di darlo per acquisito, chiariamo se parliamo di orari, luogo di lavoro o distribuzione dei compiti.'],
  ['Chi non è d’accordo lo dica adesso.', 'Invite concerns in a way that reduces the social cost of dissent.', 'Prima di chiudere, raccoglierei anche i dubbi: segnalare un rischio adesso ci aiuta, non significa ostacolare il progetto.', 'Make disagreement useful rather than disloyal.', 'A volunteer group hesitates to question an enthusiastic organiser.', 'Invite one possible difficulty from each person without demanding opposition.', 'Chiederei a ciascuno un aspetto da verificare: non per smontare l’idea, ma per darle maggiori possibilità di riuscita.'],
  ['Bene, allora siamo a posto.', 'Summarise what is agreed, identify one open question and assign a next step without overstating consensus.', 'Abbiamo concordato la prova iniziale; resta aperto come raccogliere il feedback. Propongo che il gruppo tecnico presenti due opzioni entro venerdì.', 'Close with agreement, uncertainty and ownership.', 'A planning discussion reaches partial agreement.', 'Give your own concise closing summary that separates decision from unresolved detail.', 'La data è confermata; il luogo resta da scegliere. Chi segue la logistica ci porterà due proposte al prossimo incontro.'],
])
episode('C2', 'culture', 'Argue with interpretive freedom and discipline', 'Offer a nuanced interpretation, account for counter-evidence and adapt it for a new audience.', ['rhetorical contrast', 'inference', 'audience-sensitive reformulation'], 'A story ends with a character returning an unopened letter. Earlier, they repeatedly asked for news of its sender.', [
  ['Quel gesto dimostra che non gli importa più.', 'Offer an alternative interpretation, grounded in the earlier requests for news.', 'Potrebbe essere il contrario: proprio le richieste precedenti suggeriscono che gli importi troppo per affrontare ciò che la lettera contiene.', 'Offer a plausible reading, not a claim of certainty.', 'A film character deletes a message after repeatedly rereading it.', 'Offer an interpretation other than simple indifference.', 'Il gesto potrebbe essere un tentativo di sottrarsi a un coinvolgimento troppo forte, non il segno che il messaggio non conti nulla.'],
  ['Stai leggendo nel testo quello che vuoi tu.', 'Acknowledge the risk and distinguish textual support from your own inference.', 'È un rischio reale. Le richieste di notizie sono nel testo; l’idea che il rifiuto nasca dalla paura è una mia inferenza, sostenibile ma non dimostrata.', 'Mark the boundary between observation and interpretation.', 'A discussion challenges your reading of an ironic speech.', 'Separate the speaker’s actual wording from your inference about intention.', 'Le parole sono quelle; l’intenzione ironica la deduco dal contesto, e riconosco che un altro tono cambierebbe la lettura.'],
  ['Come lo spiegheresti a chi legge poco?', 'Reformulate the interpretation in everyday language without condescension or literary terminology.', 'A volte evitiamo una notizia non perché non ci interessi, ma perché ci interessa tanto da farci paura. Quel gesto potrebbe funzionare così.', 'Keep the insight while changing the language.', 'Someone asks for a plain explanation of an unreliable narrator.', 'Explain that we hear one person’s version, which may be sincere but incomplete.', 'Ascoltiamo la storia attraverso una sola persona: può raccontarla sinceramente e tuttavia non vedere tutto.'],
])
episode('C2', 'community', 'Discuss public claims responsibly', 'Handle value conflicts, uneven evidence and persuasive rhetoric fairly.', ['qualification', 'causal reasoning', 'counterargument'], 'A local debate concerns restricting cars in the centre.', [
  ['Chi si oppone non tiene alla salute dei bambini.', 'Challenge the attribution of motives while keeping the health concern legitimate.', 'La salute dei bambini è una ragione seria, ma non possiamo dedurre da ogni obiezione un’indifferenza verso di loro; alcune riguardano accesso e alternative disponibili.', 'Defend a value without demonising dissent.', 'People opposing an event are called hostile to young people.', 'Challenge the motive claim and distinguish noise concerns from hostility.', 'Una preoccupazione per il rumore non equivale a ostilità verso i giovani; va discussa nel merito.'],
  ['Dopo la chiusura al traffico, gli incassi sono scesi: il legame è evidente.', 'Acknowledge the possible link while naming a plausible competing explanation and asking for comparison.', 'Il collegamento è possibile, ma potrebbero aver inciso anche stagionalità o lavori. Confronterei periodi e zone simili prima di attribuire tutto alla chiusura.', 'Association can matter without proving a single cause.', 'Attendance falls after a club raises fees.', 'Acknowledge the price effect may be real but suggest checking other changes too.', 'L’aumento può aver pesato, ma verificherei anche orari, offerta e cambiamenti nel numero dei soci.'],
  ['Alla fine, che cosa proporresti tu?', 'Give your own reasoned proposal, naming a cost and a safeguard rather than claiming everyone wins.', 'Proverei una chiusura in alcune fasce orarie, mantenendo accessi essenziali e verificando gli effetti sui negozi. Richiederebbe organizzazione, e non eliminerebbe ogni disagio.', 'Choose a view and acknowledge its trade-off.', 'Your village debates limiting late outdoor events.', 'Offer your own proposal with an explicit disadvantage and review mechanism.', 'Limiterei le serate più rumorose, sapendo che questo riduce alcune entrate, e rivedrei l’accordo dopo una stagione con residenti e organizzatori.'],
])
episode('C2', 'mediation', 'Synthesis without false certainty', 'Reconcile sources, retain disagreement and tailor an accurate summary to the audience.', ['source attribution', 'scope qualification', 'synthesis'], 'Two reports describe a pilot service: one says waiting times fell among participants; the other says people without internet access were underrepresented.', [
  ['Uno dice che funziona, l’altro che è un fallimento. Chi ha ragione?', 'Explain that the findings concern different dimensions and can both be true.', 'Non sono necessariamente in contraddizione: il servizio può ridurre l’attesa per chi partecipa e, nello stesso tempo, raggiungere male chi non usa internet.', 'Do not force compatible findings into opposing verdicts.', 'A school project improves test results but pupils report greater stress.', 'Explain why both findings matter without cancelling either.', 'Il miglioramento dei risultati e l’aumento dello stress possono coesistere: descrivono effetti diversi dello stesso progetto.'],
  ['Come lo presentiamo in trenta secondi al comitato?', 'Give a balanced two-sentence summary, explicitly limiting the positive finding to participants.', 'Tra i partecipanti, i tempi di attesa sono diminuiti. Il campione però rappresenta poco chi non ha accesso a internet, quindi non sappiamo ancora se il vantaggio sia estendibile a tutti.', 'Preserve scope and the unresolved question.', 'Two accounts of a cultural event report strong ticket sales but poor access for disabled visitors.', 'Summarise success and exclusion without using one to erase the other.', 'L’evento ha venduto bene, ma alcune persone non hanno potuto accedervi adeguatamente. Il successo commerciale non risolve la questione dell’accessibilità.'],
  ['Ci serve una frase convincente per annunciare il successo.', 'Offer honest, engaging wording that recognises progress without declaring the whole issue solved.', 'Direi: “Primi risultati promettenti sui tempi di attesa; il prossimo passo è verificare e migliorare l’accesso per chi oggi resta meno rappresentato”.', 'Be persuasive by being precise.', 'A group wants to advertise a mixed pilot as a complete transformation.', 'Propose a positive headline that leaves room for the work still needed.', '“Un primo passo concreto, con risultati da consolidare e ostacoli ancora da rimuovere”.'],
])
